static const mc_default DEFAULTS[] = {
	{ "eza_sel5", 1, DEF_EZA_SEL5_1, sizeof DEF_EZA_SEL5_1, "RF range 1" },
	{ "eza_sel5", 2, DEF_EZA_SEL5_2, sizeof DEF_EZA_SEL5_2, "RF range 2" },
	{ "eza_sel5", 3, DEF_EZA_SEL5_3, sizeof DEF_EZA_SEL5_3, "RF range 3" },
	{ "eza_sel5", 4, DEF_EZA_SEL5_4, sizeof DEF_EZA_SEL5_4, "RF range 4" },
	{ "eza_cspl", 1, DEF_EZA_CSPL_1, sizeof DEF_EZA_CSPL_1, "RF range 1" },
	{ "eza_cspl", 2, DEF_EZA_CSPL_2, sizeof DEF_EZA_CSPL_2, "RF range 2" },
	{ "eza_cspl", 3, DEF_EZA_CSPL_3, sizeof DEF_EZA_CSPL_3, "RF range 3" },
	{ "eza_cspl", 4, DEF_EZA_CSPL_4, sizeof DEF_EZA_CSPL_4, "RF range 4" },
	{ "eva_sel5", 0, DEF_EVA_SEL5_0, sizeof DEF_EVA_SEL5_0, "no RF-range prompt exists in this build, so the band byte is left unset" },
};

const mc_default *mc_default_by_index(size_t i)
{
	return i < sizeof DEFAULTS / sizeof DEFAULTS[0] ? &DEFAULTS[i] : NULL;
}

const mc_default *mc_default_find(const char *model, int band)
{
	const mc_default *d;
	size_t i;

	for (i = 0; (d = mc_default_by_index(i)) != NULL; i++)
		if (!strcmp(d->model, model) && (d->band == band || d->band == 0))
			return d;
	return NULL;
}
